.admin-form .submit-row {
    display: flex;
    flex-wrap: wrap;
    gap: .5rem;
    padding-bottom: calc(1rem + env(safe-area-inset-bottom, 0px));
}

.admin-form .submit-row > .btn {
    max-width: 100%;
    white-space: normal;
}

